import { adapters, constants, utils, helpers } from '@cloudbase/utilities'
import { SDKAdapterInterface, CloudbaseAdapter, IRequestConfig } from '@cloudbase/adapter-interface'
import {
  ICloudbaseConfig,
  ICloudbaseUpgradedConfig,
  ICloudbase,
  ICloudbaseExtension,
  KV,
  ICloudbasePlatformInfo,
  EndPointKey,
  ICloudbaseApis,
  ICredentialsInfo,
} from '@cloudbase/types'
import { ICloudbaseAuth } from '@cloudbase/types/auth'
import { registerComponent, registerHook } from './libs/component'
import { getWxDefaultAdapter, Platform } from './libs/adapter'
import { ICloudbaseComponent, ICloudbaseHook } from '@cloudbase/types/component'
import { ICloudbaseCache } from '@cloudbase/types/cache'
import { initCache, getCacheByEnvId, getLocalCache } from './libs/cache'
import { ICloudbaseRequest } from '@cloudbase/types/request'
import { initRequest, getRequestByEnvId } from './libs/request'
import {
  getSdkName,
  setSdkVersion,
  setRegionLevelEndpoint,
  setSdkName,
  setGatewayEndPointWithEnv,
  type ISetEndPointWithKey,
  setEndPointInfo,
  getEndPointInfo,
  getSdkVersion,
  DEFAULT_PROTOCOL,
} from './constants/common'
import { i18nProxy, LANGS } from './libs/lang'
import { registerThrowConfig } from './libs/throw'
export { getBaseEndPoint } from './constants/common'
export { LANGS } from './libs/lang'
const { useAdapters, useDefaultAdapter } = adapters
const { ERRORS, COMMUNITY_SITE_URL } = constants
const { printWarn } = utils
const { catchErrorsDecorator } = helpers

/**
 * @constant 默认请求超时时间（毫秒）
 * 仅非 Node 环境使用；Node 环境默认不设置 timeout（不超时）
 */
const DEFAULT_TIMEOUT = 15000

/**
 * @constant 默认配置
 */
const DEFAULT_INIT_CONFIG: Partial<ICloudbaseConfig> = {
  persistence: 'local', // 持久化存储类型
}

// timeout上限10分钟
const MAX_TIMEOUT = 1000 * 60 * 10
// timeout下限100ms
const MIN_TIMEOUT = 100

const extensionMap: KV<ICloudbaseExtension> = {}

class Cloudbase implements ICloudbase {
  public authInstance: ICloudbaseAuth
  public oauthInstance: any
  public requestClient: any
  public oauthClient: any
  public version: string
  public auth: ICloudbase['auth'] & ICloudbaseAuth
  public apis: ICloudbaseApis
  /**
   * init() 时注入的实例级 request。
   * 同一 env 多次 init（如 Node 服务端以不同 accessKey 初始化用户态 client）时，
   * 保证各 app 实例的认证状态互不覆盖；未注入时兜底走 env 级 requestMap。
   */
  public requestInstance: ICloudbaseRequest
  private cloudbaseConfig: ICloudbaseConfig

  constructor(config?: ICloudbaseConfig) {
    this.cloudbaseConfig = config ? config : this.cloudbaseConfig
    this.authInstance = null
    this.oauthInstance = null
    this.requestInstance = null
    this.version = getSdkVersion()
  }

  get config() {
    return this.cloudbaseConfig
  }

  get platform(): ICloudbasePlatformInfo {
    return Platform
  }

  get cache(): ICloudbaseCache {
    return getCacheByEnvId(this.cloudbaseConfig.env)
  }

  get localCache(): ICloudbaseCache {
    return getLocalCache(this.cloudbaseConfig.env)
  }

  get request(): ICloudbaseRequest {
    // 实例级 request 优先：避免同 env 多 init 时认证状态（accessKey/oauth token）互相覆盖；
    // 单例或 legacy 实例（未经过 init() 注入）兜底走 env 级 requestMap
    return this.requestInstance || getRequestByEnvId(this.cloudbaseConfig.env)
  }

  @catchErrorsDecorator({
    mode: 'sync',
    title: 'Cloudbase 初始化失败',
    messages: [
      '请确认以下各项：',
      '  1 - 调用 cloudbase.init() 的语法或参数是否正确',
      '  2 - 如果是非浏览器环境，是否配置了安全应用来源（https://docs.cloudbase.net/api-reference/webv3/adapter#%E7%AC%AC-2-%E6%AD%A5%E9%85%8D%E7%BD%AE%E5%AE%89%E5%85%A8%E5%BA%94%E7%94%A8%E6%9D%A5%E6%BA%90）',
      `如果问题依然存在，建议到官方问答社区提问或寻找帮助：${COMMUNITY_SITE_URL}`,
    ],
  })
  public init(config: ICloudbaseConfig & { lang?: LANGS } = { env: '' }): Cloudbase {
    config.endPointMode = config.endPointMode || 'GATEWAY'

    // 初始化时若未兼容平台，则使用默认adapter
    if (!Platform.adapter) {
      this.useDefaultAdapter()
    }

    // 在判断config.env之前，先处理node环境的配置
    config = this.dealNodeAdapterConfig(config)

    // 统一 throw 开关：throw 优先，throwOnCode 仅 init 时作为别名（canonicalize 后不再保留）。
    // 后续 request/database/functions/storage 经典/本地校验统一读 config.throw。
    config.throw = config.throw ?? config.throwOnCode ?? true
    delete config.throwOnCode

    if (!config.env) {
      throw new Error(JSON.stringify({
        code: ERRORS.INVALID_PARAMS,
        msg: 'env must not be specified',
      }),)
    }

    this.isInitialized(config)

    // Node 环境默认不设置 timeout（不超时），其他环境默认 15000
    const defaultTimeout = this.isNodeEnv() ? undefined : DEFAULT_TIMEOUT
    const resolvedTimeout = config.timeout || defaultTimeout

    // 只挑选 NodeRequest 需要的字段传给 reqClass，
    // 供其在使用时通过 getSecretInfo(this.config) 实时读取密钥，
    // 避免依赖全局 INIT_CONFIG 快照导致多实例配置串用；
    // 同时不展开 _fromApp/oauthClient 等复杂对象，防止 getSecretInfo 深拷贝时循环引用报错。
    // accessKey 仅带用户显式传入的（CLOUDBASE_APIKEY 不持久化），
    // 让 getSecretInfo 命中「accessKey 优先」分支：显式传 accessKey 即走 accessKey 模式，
    // 不被环境变量临时密钥覆盖
    const reqConfig: IRequestConfig & ICloudbaseConfig = {
      env: config.env,
      region: config.region,
      accessKey: config.accessKey,
      context: config.context,
      auth: config.auth,
      timeout: resolvedTimeout,
      timeoutMsg: resolvedTimeout
        ? `[${getSdkName()}][REQUEST TIMEOUT] request had been abort since didn't finished within${
          resolvedTimeout / 1000
        }s`
        : undefined,
    }

    this.requestClient = new Platform.adapter.reqClass(reqConfig)

    this.cloudbaseConfig = {
      ...DEFAULT_INIT_CONFIG,
      ...config,
      timeout: resolvedTimeout,
      i18n: i18nProxy(Platform, config),
    }

    // 注册实例 config，供 setThrowOnCode 自由函数（node-sdk 顶层导出）联动改写 throw
    registerThrowConfig(this.cloudbaseConfig)

    delete (this.cloudbaseConfig as any).lang
    // 修正timeout取值
    this.cloudbaseConfig.timeout = this.formatTimeout(this.cloudbaseConfig.timeout)
    // 初始化cache和request
    const { env, persistence, debug, timeout, oauthClient, i18n } = this.cloudbaseConfig
    initCache({ env, persistence, debug, platformInfo: this.platform })

    setRegionLevelEndpoint(env, config.region || '')
    setGatewayEndPointWithEnv(env, DEFAULT_PROTOCOL, config.intl)

    const app = new Cloudbase(this.cloudbaseConfig)
    // 实例级 request 绑定：app 的所有组件（models/functions/database/storage...）
    // 均通过 app.request getter 取 request，绑定后不再受同 env 后续 init 影响
    app.requestInstance = initRequest({
      env,
      region: config.region || '',
      timeout,
      oauthClient,
      _fromApp: app,
      i18n,
      endPointMode: config.endPointMode,
      auth: config.auth,
      context: config.context,
      accessKey: config.accessKey,
      throw: config.throw,
    })
    app.requestClient = this.requestClient
    ;(this as any)?.fire?.('cloudbase_init', app)

    this.try2InitAuth(app)

    // node环境可以从adapter获取nodeTool的方法
    if (Platform.adapter?.nodeTool) {
      Platform.adapter?.nodeTool(app, this.cloudbaseConfig)
    }

    return app
  }

  public updateConfig(config: ICloudbaseUpgradedConfig) {
    const { persistence, debug } = config
    this.cloudbaseConfig.persistence = persistence
    this.cloudbaseConfig.debug = debug
    // persistence改动影响cache
    initCache({ env: this.cloudbaseConfig.env, persistence, debug, platformInfo: this.platform })
  }

  /**
   * 运行时切换「抛错 vs 返回 {code}」行为（实例级）。
   * 直接改写本实例的 config.throw，因此所有读取 config.throw 的
   * 下游（request 层 / database / functions / storage 经典 / 本地校验）会天然联动。
   */
  public setThrowOnCode(value: boolean) {
    this.cloudbaseConfig.throw = value
  }

  public updateLang(lang: LANGS) {
    if (!lang || lang === this.cloudbaseConfig.i18n?.lang) return

    this.cloudbaseConfig.i18n.lang = lang
  }

  public registerExtension(ext: ICloudbaseExtension) {
    extensionMap[ext.name] = ext
  }
  @catchErrorsDecorator({
    title: '调用扩展能力失败',
    messages: [
      '请确认以下各项：',
      '  1 - 调用 invokeExtension() 的语法或参数是否正确',
      '  2 - 被调用的扩展能力是否已经安装并通过 registerExtension() 注册',
      `如果问题依然存在，建议到官方问答社区提问或寻找帮助：${COMMUNITY_SITE_URL}`,
    ],
  })
  public async invokeExtension(name: string, opts: any) {
    const ext = extensionMap[name]
    if (!ext) {
      throw new Error(JSON.stringify({
        code: ERRORS.INVALID_PARAMS,
        msg: `extension:${name} must be registered before invoke`,
      }),)
    }

    return await ext.invoke(opts, this)
  }

  public useAdapters(adapters: CloudbaseAdapter | CloudbaseAdapter[], options?: any) {
    const { adapter, runtime } = useAdapters(adapters, options) || {}
    adapter && (Platform.adapter = adapter as SDKAdapterInterface)
    runtime && (Platform.runtime = runtime as string)
  }

  public registerHook(hook: ICloudbaseHook) {
    registerHook(Cloudbase, hook)
  }

  public registerComponent(component: ICloudbaseComponent) {
    registerComponent(Cloudbase, component)
  }

  public registerVersion(version: string) {
    setSdkVersion(version)
    this.version = version
  }

  public registerSdkName(name: string) {
    setSdkName(name)
  }

  /**
   * 检查当前 Cloudbase 实例是否已完成初始化
   *
   * @example
   * ```javascript
   * import cloudbase from '@cloudbase/js-sdk'
   *
   * // 初始化前
   * console.log(cloudbase.isInitialized()) // false
   *
   * const app = cloudbase.init({ env: 'your-env-id' })
   *
   * // 初始化后
   * console.log(app.isInitialized()) // true
   * ```
   *
   * @returns {boolean} 是否已初始化
   */
  public isInitialized(config = this.cloudbaseConfig): boolean {
    // 检测常见占位符 env 值，在开发阶段给出友好提示
    const PLACEHOLDER_PATTERNS = [
      'your-env-id',
      'your-envid',
      'your_env_id',
      'xxx-yyy',
      'xxxx-yyy',
      'envId',
      'env-id',
      'your-environment-id',
      'REPLACE_ME',
    ]
    if (typeof config.env === 'string' && PLACEHOLDER_PATTERNS.some(p => config.env.toLowerCase() === p.toLowerCase())) {
      printWarn(
        ERRORS.INVALID_PARAMS,
        `[CloudBase] 检测到环境 ID "${config.env}" 可能是占位符，请替换为真实的环境 ID。\n`
          + '  获取方式：登录腾讯云开发平台 → 环境管理 → 环境设置 → 环境 ID\n'
          + '  建议通过环境变量配置：process.env.CLOUDBASE_ENV 或 import.meta.env.VITE_CLOUDBASE_ENV',
      )
    }

    return !!config?.env
  }

  /** 设置 tcb api 的 endpoint */
  public registerEndPoint(url: string, protocol?: 'http' | 'https') {
    setEndPointInfo({ baseUrl: url, protocol, env: this.config.env, endPointKey: 'CLOUD_API' })
  }

  /** 设置网关/tcb api的 endPoint，通过 key 指定 */
  public registerEndPointWithKey(props: ISetEndPointWithKey) {
    setEndPointInfo({
      env: this.config.env,
      endPointKey: props.key,
      baseUrl: props.url,
      protocol: props.protocol,
    })
  }

  /**
   * 一次性设置所有端点，只需传入 host 地址，自动拼接路径
   * @param host - 主机地址，如 "43.144.98.4" 或 "//43.144.98.4"
   * @param protocol - 协议，默认 "http"
   */
  public registerHost(host: string, protocol: 'http' | 'https' = 'http') {
    // 去掉可能的协议前缀和前导 //
    const cleanHost = host.replace(/^(https?:)?\/\//, '')
    const baseHost = `//${cleanHost}`
    // CLOUD_API 端点: /web
    setEndPointInfo({ baseUrl: `${baseHost}/web`, protocol, env: this.config.env, endPointKey: 'CLOUD_API' })
    // GATEWAY 端点: /v1
    setEndPointInfo({ baseUrl: `${baseHost}/v1`, protocol, env: this.config.env, endPointKey: 'GATEWAY' })
  }

  /** 拿网关/tcb api的 endPoint，通过 key 指定 */
  public getEndPointWithKey(key: EndPointKey) {
    const info = getEndPointInfo(this.config.env, key)
    return {
      BASE_URL: info.baseUrl,
      PROTOCOL: info.protocol,
    }
  }

  // 解析URL参数
  public parseCaptcha(url) {
    return utils.parseCaptcha(url)
  }

  private useDefaultAdapter() {
    const { adapter, runtime } = useDefaultAdapter.bind(this)()
    Platform.adapter = adapter as SDKAdapterInterface
    Platform.runtime = runtime as string
  }

  /**
   * 判断当前是否为 Node 环境（存在 process 且 adapter 提供了 getSecretInfo）
   */
  private isNodeEnv(): boolean {
    return (
      typeof process !== 'undefined'
      && typeof process.env !== 'undefined'
      && !!Platform.adapter?.getSecretInfo
    )
  }

  private formatTimeout(timeout: number | undefined) {
    // 未设置 timeout（如 Node 环境默认不超时）时直接放行，不做上下限修正
    if (timeout === undefined || timeout === null) {
      return timeout
    }
    switch (true) {
      case timeout > MAX_TIMEOUT:
        printWarn(ERRORS.INVALID_PARAMS, 'timeout is greater than maximum value[10min]')
        return MAX_TIMEOUT
      case timeout < MIN_TIMEOUT:
        printWarn(ERRORS.INVALID_PARAMS, 'timeout is less than maximum value[100ms]')
        return MIN_TIMEOUT
      default:
        return timeout
    }
  }

  private try2InitAuth(app) {
    try {
      app.auth()
    } catch (error) {
      console.log('try2InitAuth error:', error)
    }
  }

  /**
   * 处理 Node 环境下 adapter 的配置信息
   *
   * 仅持久化 env、credentials 与用户显式传入的密钥：
   * - env 在 init 后需用于 URL 拼接、cache key 等多处，必须固定
   * - credentials 来自用户显式传入（私钥认证），需要搬到 config.auth.credentials 供 createTicket 等使用
   * - 用户显式传入的 secretId/secretKey/sessionToken/secretType（顶层 node-sdk 风格
   *   或 config.auth 风格）统一规范到 config.auth，供 request.ts 从 this.config.auth 直接读取签名
   *
   * 不持久化来自环境变量的密钥（TENCENTCLOUD_* / CLOUDBASE_APIKEY）：
   * - 改由 request / getClientCredential 在使用时通过 getSecretInfo() 实时读取，
   *   以支持云函数进程复用场景下 setenv 更新密钥后立即生效
   * - getSecretInfo() 的优先级保证"显式传入 > 环境变量"，每级内"accessKey > ak/sk"
   *
   * @param config - 云开发初始化配置对象
   * @returns 补充了 env / credentials / 用户显式密钥后的配置对象
   */
  private dealNodeAdapterConfig(config: ICloudbaseConfig) {
    if (this.isNodeEnv()) {
      const secretInfo = Platform.adapter?.getSecretInfo(config) as {
        env: string
        credentials?: string
      }

      // node 环境可能可以从上下文获取 env，用户未显式指定时自动填充
      // env 为 symbol（SYMBOL_CURRENT_ENV / SYMBOL_DEFAULT_ENV）时，
      // getSecretInfo 已将其解析为真实环境 ID，这里用解析结果替换 symbol，
      // 避免后续 isInitialized / URL 拼接等环节拿到 symbol 而出错
      if (!config.env || typeof config.env === 'symbol') {
        config.env = secretInfo.env
      }

      // credentials 语义为对象（ICredentialsInfo），来自用户显式传入（顶层或 config.auth），
      // getSecretInfo 已合并两个来源，这里统一搬到 config.auth.credentials，
      // 供 createTicket 等直接读 config.auth.credentials 的地方使用
      if (secretInfo.credentials) {
        config.auth = {
          ...config.auth,
          credentials: secretInfo.credentials as unknown as ICredentialsInfo,
        }
      }

      // 用户显式传入的密钥（顶层 node-sdk 风格或 config.auth 风格）统一规范到 config.auth，
      // 供 request.ts 从 this.config.auth 直接读取签名；
      // 仅持久化用户显式传入的密钥，环境变量（TENCENTCLOUD_* / CLOUDBASE_APIKEY）来的
      // 不持久化，仍在使用时通过 getSecretInfo() 实时读取。
      // 若不规范化，顶层风格（init({ secretId, secretKey })）会因 reqConfig 不含顶层字段，
      // 在 getSecretInfo() 里被 CLOUDBASE_APIKEY 等环境变量覆盖
      const topConfig = config as any
      const explicitSecretId = topConfig.secretId || config.auth?.secretId
      const explicitSecretKey = topConfig.secretKey || config.auth?.secretKey
      if (explicitSecretId && explicitSecretKey) {
        const explicitSessionToken = topConfig.sessionToken || config.auth?.sessionToken || ''
        config.auth = {
          ...config.auth,
          secretId: explicitSecretId,
          secretKey: explicitSecretKey,
          sessionToken: explicitSessionToken,
          secretType: config.auth?.secretType || (explicitSessionToken ? 'SESSION_SECRET' : 'SECRET'),
        }
      }
    }

    return config
  }
}

// 类型导出
export type { Cloudbase }

// 值导出
export const cloudbase: ICloudbase = new Cloudbase()

const wxAdapter = getWxDefaultAdapter()
if (wxAdapter) {
  cloudbase.useAdapters(wxAdapter)
}

// 默认导出实例
export default cloudbase
